pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress, smooth in [0,1]
    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    // Normalized post-residual (fraction of capacity left over)
    let cap = bin_capacity.max(1) as f64;
    let pr_frac = post_residual as f64 / cap;

    // Non-linear coupling: dead space is penalized more aggressively as the stream progresses.
    // Quadratic-in-progress amplification of post-residual, plus a smooth cubic term.
    let progress_amp = 1.0 + 2.0 * progress * progress;
    score += progress_amp * (pr_frac * cap) * (0.5 + pr_frac * pr_frac);

    // Smooth interaction: small post-residuals (tight fits) are rewarded proportionally
    // to how much of the bin was consumed, with a saturating (1 - exp-like) polynomial form.
    let fill = 1.0 - pr_frac;
    let tightness = fill * fill * (3.0 - 2.0 * fill); // smoothstep in [0,1]
    score -= 8.0 * tightness * (1.0 + progress);

    // Penalize bins whose residual is far from the mean residual (smooth quadratic coupling),
    // encouraging homogenization of open-bin residuals over time.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * dev / cap * (0.5 + progress);

    // Lookahead coupling: if the next item could use the resulting post_residual,
    // reward leaving exactly that much space (smooth compatibility kernel).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let compat = (-gap / cap).exp();
        score -= 6.0 * compat * (1.0 + progress);
    } else {
        // Last item: strongly prefer minimizing leftover space.
        score += 3.0 * pr_frac * cap;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible (smooth penalty scaling with badness).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let badness = pr_frac;
        score -= 10.0 * (1.0 - badness * badness);
    }

    // Mild preference for keeping the number of open bins bounded as stream progresses.
    score += 0.05 * (open_bins_count as f64) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how it divides the capacity
    let pr = post_residual;
    if pr > 0 {
        // Fractional capacity class of the leftover
        let frac = pr as f64 / cap;
        // Dead-space penalty grows superlinearly for small unusable leftovers
        if pr < 10 {
            score += 60.0 * (10.0 - pr as f64);
        } else if pr < 20 {
            score += 12.0 * (20.0 - pr as f64);
        } else if pr < 30 {
            score += 4.0 * (30.0 - pr as f64);
        }

        // Modulo classes: leftovers near multiples of common item sizes are reusable
        for m in [10u32, 20, 25, 30, 40, 50] {
            let r = pr % m;
            let d = r.min(m - r) as f64;
            score += 0.6 * d; // penalize leftovers far from divisible classes
        }

        // Reward leftovers that can host mid-size future items
        if pr >= 40 { score -= 8.0; }
        if pr >= 25 && pr < 40 { score -= 3.0; }
        let _ = frac;
    } else {
        // Perfect fit: strong reward
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - 0.2 * slack; // next item fits here
            if pr == next_item_size { score -= 15.0; } // perfect chain
        } else {
            // next item won't fit: mild penalty scaled by gap
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        score = 40.0 + 2.0 * mean_residual - 0.5 * pr as f64;
        if open_bins_count == 0 { score -= 60.0; }
        if fitting_bins_count == 0 { score -= 20.0; }
        // late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure against fragmenting many open bins
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: residual too small for any plausible future item (min size 1..~15).
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 25.0;
    }

    // Moderate dead space penalty scaled by how much of the bin is wasted.
    if post_residual >= 15 {
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * 40.0;
    }

    // Fill high bins first: reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 120.0 + open_bins_count as f64 * 15.0;
        // Late in stream, opening new bins is even less attractive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
    } else {
        // Using an existing bin reduces open-bin pressure slightly.
        score -= open_bins_count as f64 * 2.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    }
    // If next item would fit but leave another dead gap, mild penalty.
    if next_item_size > 0 && next_item_size < post_residual && post_residual - next_item_size < 15 {
        score += 20.0;
    }

    // Prefer bins whose residual is below average (consolidate emptier space).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: match post_residual against next_item_size ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            // Perfect fit for the lookahead item: strongly reward.
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mild reward proportional to tightness.
            let slack = post_residual as f64 - nxt;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize dead space.
            let dead = nxt - post_residual as f64;
            score += 4.0 * (dead / bin_capacity as f64).min(1.0);
        }
    }

    // --- Relative residual vs mean across open bins ---
    // Bins with residual well below mean are "tight" -> prefer using them first.
    let mean_gap = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score -= 6.0 * mean_gap;

    // --- Last-chance bonus: only this bin fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin: only attractive if no tight reuse exists.
        // Penalize mildly so reuse wins unless reuse scores are worse.
        score += 3.0;
        // If lookahead doesn't match an empty bin's post placement, discourage.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // --- Late-stream tightening: waste matters more as stream progresses ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += score * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize large dead space asymmetrically: residuals too small for typical
    // future items are wasted, so punish very small but nonzero post residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // post_residual unusable by next item: mild penalty unless residual tiny
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate handling: an empty bin is a costly resource; penalize it
    // unless the item is huge relative to capacity (poor fit anywhere else anyway).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is fine for large items, wasteful for small ones.
        score += 40.0 * (1.0 - fill_ratio);
        // Early in the stream, opening bins is more acceptable (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual => prefer consolidation
    // into bins below mean residual (filling the emptiest bins first).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Prefer bins whose post residual lands on "reusable" sizes divisible by 10.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, amplified by stream progress.
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Non-linear coupling: post_residual vs mean residual — penalize outliers.
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (1.0 + progress);

    // Smoothly reward tight fits (post_residual near zero) via saturating term.
    score -= 20.0 * (-norm_pr * 8.0).exp() * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward bins whose post-residual can hold next item,
    // penalize those that cannot (smooth logistic in gap size).
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        let logistic = 1.0 / (1.0 + (-gap / 10.0).exp());
        score += 12.0 * logistic;
    }

    // New-bin candidate: mildly penalize opening a bin early, allow it late
    // or when existing residuals are large (smooth interaction).
    if bin_residual == bin_capacity {
        score = cap * (1.0 - progress) + 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "nice" multiples of small divisors are more reusable.
    let pr = post_residual;
    let nice_bonus = if pr == 0 {
        6.0 // perfect fill: strongly favored
    } else if pr % 10 == 0 {
        -1.5
    } else if pr % 5 == 0 {
        -1.0
    } else if pr % 25 == 0 {
        -2.0
    } else {
        0.5 // awkward residual
    };
    score += nice_bonus;

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 range, use conservative threshold)
    if pr > 0 && pr < 10 {
        score += 4.0;
    }

    // Coupling with lookahead: reward residuals that exactly fit next item (harmonic chaining)
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 3.5;
        } else if pr >= next_item_size && pr % next_item_size.max(1) == 0 {
            score -= 2.0;
        } else if pr < next_item_size && pr > 0 {
            score += 1.5; // this bin becomes dead after this placement
        }
        // integer-division threshold: how many next items could still fit
        let fits_next = pr / next_item_size.max(1);
        score -= fits_next as f64 * 0.5;
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual
    let fill_frac = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= fill_frac * 3.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity means fresh empty bin.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more when other bins fit and residual is not tight.
        let mut new_bin_penalty = 3.0;
        if fitting_bins_count > 0 {
            new_bin_penalty += 2.5;
        }
        // Late in the stream, opening new bins wastes capacity; penalize more.
        new_bin_penalty += 2.0 * progress;
        // If item is large relative to capacity, a fresh bin is more reasonable.
        new_bin_penalty -= (item_size as f64 / bin_capacity as f64) * 2.0;
        // If mean residual across open bins is too small to matter, new bin is fine.
        if mean_residual < item_size as f64 {
            new_bin_penalty -= 2.0;
        }
        score += new_bin_penalty;
    }

    // Mild pressure to consolidate: fewer open bins relative to items favors reuse
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 0.3;
    }

    // Prefer bins whose residual deviates favorably from the mean (more packed bins)
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftovers (below min item size 1..=small threshold)
    // are wasted capacity; punish gaps that are tiny but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits strongly (perfect fit gets big bonus).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness * tightness;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: many open bins -> discourage opening yet another bin,
    // encourage consolidating into existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable when few bins are open or residuals are large,
        // but penalized under pressure.
        score += pressure * 3.0;
        // A new bin is attractive if the next item could pair with what remains here.
        if next_item_size > 0 {
            let pair_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score += pair_gap * 0.5;
        }
    } else {
        // Existing bin: mild reward to counteract new-bin preference under pressure.
        score -= pressure * 1.5;
        // Lookahead: if the post_residual exactly accommodates the next item, reward.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 35.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Penalize bins whose residual deviates from the mean (fragmentation signal).
        score += (bin_residual as f64 - mean_residual).abs() * 0.3;
    }

    // Slight late-stream bias: keep bins tight as the stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how little slack remains after both.
            let two_step_slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - 1.5 * two_step_slack;
        } else {
            // Next item does NOT fit this bin after placement: penalize if the leftover
            // post_residual is small (dead space) relative to typical residuals.
            let dead = (post_residual as f64) / mean_residual.max(1.0);
            score += 30.0 * (1.0 - dead.min(1.0));
        }
    } else {
        // Last item: just prefer tightest fit (post_residual baseline handles it).
        score += 0.0;
    }

    // Prefer bins whose residual is already below average (consolidating waste).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Mild penalty for opening new bins early in the stream when many bins are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * (1.0 - tight) * 30.0;

    // Dead-space penalty: residuals too small for the smallest item are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing here blocks the next item's fit in this bin
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or many bins are already open (consolidate before expanding).
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 55.0 + open_f * 5.0;
        // But if the current bin would leave a tiny dead fragment, opening a fresh
        // bin becomes relatively more attractive.
        if post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
        // Early in the stream with few open bins, opening is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
    }

    // Global state coupling: if mean residual is large, prefer bins below the mean
    // (drain the emptiest bins first) to consolidate fragments.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    // Mild preference for filling fuller bins overall.
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post-residual with a non-linear (quadratic) term.
    let mut score = norm_pr + 0.35 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, prefer tight packing (low post-residual); later, accept
    // larger residuals to avoid opening bins needlessly.
    let coupling = (0.6 * progress - 0.3) * norm_pr * (1.0 - norm_pr);
    score -= 2.0 * coupling;

    // Reward filling a bin nearly full, more strongly as stream progresses.
    let fill = 1.0 - norm_pr;
    score -= fill * fill * (0.5 + 1.5 * progress);

    // Last-chance bin: strong reward so we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 1.2 + 0.8 * progress;
    }

    // Penalize bins far below mean residual (wasted space relative to pool),
    // with smooth cubic coupling to progress.
    let dev = (mean_residual - pr) / cap;
    score += 0.4 * dev * dev * dev.abs().max(0.0) * (1.0 - progress);

    // Lookahead: reward residuals that can accommodate the next item,
    // scaled smoothly by how close the next item fits.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr >= nx) as i32 as f64;
        let snug = (nx / cap).clamp(0.0, 1.0);
        score -= fits_next * (0.3 + 0.5 * snug) * (1.0 - progress);
    }

    // Mild penalty for many open bins early on (encourage consolidation).
    score += 0.02 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer-division bands and modulo arithmetic w.r.t. capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: tiny dead space (<= 10% capacity) -> excellent, reward strongly.
    if post_residual <= bin_capacity / 10 {
        score -= 25.0 + 0.5 * (bin_capacity / 10 - post_residual) as f64;
    }
    // Class B: medium leftover (10%..25%) -> mild reward, since many items (1..25)
    // could still fit later.
    else if post_residual <= bin_capacity / 4 {
        score -= 8.0;
    }
    // Class C: awkward leftover (25%..40%) -> penalize: too big to close, too
    // small for typical items; dead-space risk.
    else if post_residual <= (bin_capacity * 2) / 5 {
        score += 6.0 + 0.1 * (post_residual as f64);
    }
    // Class D: large leftover -> fine, bin stays usable.
    else {
        score -= 3.0;
    }

    // Modulo harmonic bonus: leftover that is a multiple of small granularities
    // (e.g. divisible by 5 or 10) pairs well with future items on integer grids.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    } else {
        score += 1.5; // non-harmonic leftover slightly penalized
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= bin_capacity / 10 {
                score -= 12.0; // chain leads to near-perfect packing
            } else if next_post <= bin_capacity / 4 {
                score -= 5.0;
            } else {
                score += 2.0; // chain leaves awkward space
            }
        } else {
            // next item cannot follow into this bin; leftover likely wasted
            score += 3.0 + 0.05 * pr;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using
    // it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
        // but if it creates huge awkward leftover, soften the reward
        if post_residual > (bin_capacity * 2) / 5 && post_residual < (bin_capacity * 3) / 5 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when all existing fits are bad.
        // Base penalty keeps preference for existing bins; relax when many open
        // bins with high mean residual indicate fragmentation.
        let mut new_bin_score = cap * 0.55;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual > cap * 0.5 && open_bins_count > 2 {
            new_bin_score -= 10.0; // fragmented state, fresh bin may be better
        }
        if next_item_size > 0 && next_item_size > post_residual.min(bin_capacity / 2) {
            new_bin_score -= 5.0;
        }
        new_bin_score += 5.0 * (1.0 - progress);
        score = score.min(new_bin_score + cap * 0.4);
        // Return the new-bin score directly so comparison is meaningful.
        return new_bin_score;
    }

    // Mild preference for fuller bins relative to the fleet mean residual:
    // placing into bins below mean residual balances the pool.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Slight late-stream tightening: as the stream progresses, avoid spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable for future
    // items (min size 1 assumed, but tiny gaps waste capacity) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 40.0;

    // Penalize leaving a gap that exactly wastes capacity relative to mean residual.
    if post_residual as f64 > mean_residual * 1.5 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor
    // compacting into existing bins, and discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure so it only wins when
        // existing fits are truly bad.
        score += 60.0 + pressure * 4.0;
    } else {
        score -= pressure * 0.8;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 {
            score += 10.0; // next item can't use this bin's remainder
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Penalize dead space that no plausible future item can use.
    // Items are 1..=100; residual smaller than the smallest plausible item is dead weight.
    if post_residual > 0 {
        let usable = if post_residual >= 50 { 1.0 }
                     else if post_residual >= 20 { 0.6 }
                     else { 0.25 };
        score += (1.0 - usable) * (post_residual as f64) * 0.35;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Reward leaving room the next item can partially use, scaled by how well it fits.
            let frac = (next_item_size as f64) / (post_residual as f64);
            score -= 10.0 * frac;
        } else {
            // Next item won't fit here: slight penalty for leaving awkward gap.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing fits are poor
    // (i.e., this call has bin_residual == bin_capacity) and mean residual is fragmented.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 12.0;
        // If open bins have scattered residuals, a fresh bin is more attractive.
        let fragmentation = (mean_residual - (post_residual as f64)).abs() / cap;
        if fragmentation > 0.4 { new_bin_penalty -= 4.0; }
        // Late in the stream, avoid opening new bins (waste).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty += 10.0 * progress;
        // Many open bins already: discourage adding more.
        new_bin_penalty += (open_bins_count as f64).ln().max(0.0) * 2.0;
        score += new_bin_penalty;
    } else {
        // Mild bonus for keeping bins consolidated when many are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 0.8;
    }

    // Time-horizon modulation: early on, be greedy about tightness; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 4.0 * tight;
    score += progress * (bin_residual as f64 - post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Base: reward small post_residual (tight fits) via convex quadratic.
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = x * x * (2.0 + 2.0 * progress) + x * (1.0 - progress);

    // Cubic smooth term: penalize mid-range residuals more as stream progresses.
    score += (x * x * x) * (4.0 * progress);

    // Reward using bins that are already fairly full (small bin_residual).
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= fill * fill * 2.0;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: penalize if post_residual cannot fit next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) / cap * 3.0;
        } else {
            score -= 1.5 * (1.0 - progress);
        }
    }

    // Penalize spreading across too many open bins late in the stream.
    score += (open_bins_count as f64) * 0.05 * progress;

    // Prefer bins with residual near mean residual (harmonic packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 2.0;

    // New-bin candidate: only attractive early or when current bin residual is tiny/dead.
    if bin_residual == bin_capacity {
        score = 6.0 - 4.0 * progress;
        if post < 10.0 {
            score -= 2.0; // keep fresh bins for large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues that commonly pair with
    // small items (1..=20) are more reusable than odd dead space.
    let r = post_residual;
    let residue_class = r % 10;
    let harmonic_bonus = match residue_class {
        0 => 8.0,             // round residual: pairs with decadal items
        5 => 5.0,             // half-decade residual
        _ => -2.0,            // irregular residual is dead space
    };
    score -= harmonic_bonus;

    // Integer-division thresholds on post_residual: classify leftover into
    // usable bands (fits a "small" item vs a "medium" item).
    let small_fit = (r / 25) as f64;       // 0,1,2,3,4 bands
    score -= 6.0 * small_fit;

    // Perfect-fill reward: modulo coupling between residual and capacity.
    if bin_residual % 25 == 0 && item_size % 25 == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: does the leftover's class match the next item class?
    if next_item_size > 0 {
        let next_class = next_item_size % 10;
        if next_item_size <= r {
            // next item fits this bin: reward if classes align (harmonic pair)
            let align = if next_class == 0 {
                residue_class == 0
            } else {
                next_class == residue_class || residue_class >= next_class
            };
            if align {
                score -= 10.0;
            }
            // exact match of post-placement space to next item
            if r == next_item_size {
                score -= 20.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large waste
            score += 4.0 + (r as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // are nearly full (low mean residual) or many bins already open.
    if bin_residual == bin_capacity {
        score += 40.0
            - 0.5 * mean_residual
            - 2.0 * (open_bins_count as f64).sqrt()
            + (step_index as f64 / (total_items as f64).max(1.0)) * 10.0;
    } else {
        // Prefer tighter bins: reward small post_residual relative to capacity.
        score -= (1.0 - (post_residual as f64) / (bin_capacity as f64)) * 12.0;
        // Favor bins whose fill fraction is high (capacity fraction logic).
        let fill_frac = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
        score -= 10.0 * fill_frac;
        // Slight preference to keep many open bins consolidated.
        if open_bins_count > 8 {
            score -= 3.0;
        }
    }

    // Modulo threshold on item size: large items (>= 50) should go into
    // emptier bins to avoid fragmentation.
    if item_size >= 50 {
        score += (post_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize residuals that cannot fit the lookahead item if a similar size is likely.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // room for the next item too
    }

    // Reward using bins that are already open when many are open (pressure to close bins).
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= open_pressure * 15.0 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor placing here if this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Avoid wasting a nearly empty bin when other options exist; favor new bins when
    // all open bins would leave large dead space relative to mean residual.
    if bin_residual == bin_capacity {
        // New bin candidate: attractive if typical open-bin fit is poor.
        let waste_estimate = (bin_residual as f64 - item_size as f64) - mean_residual;
        if waste_estimate < 0.0 {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += tightness * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward if the next item fits the leftover space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 0.5;
            if next_item_size == post_residual {
                score -= 500.0; // chained perfect fit
            }
        } else {
            // Penalize leftovers too small for the next item (dead space risk),
            // scaled by how close the leftover is to being useless.
            let dead = post_residual as f64 / bin_capacity as f64;
            let next_rel = next_item_size as f64 / bin_capacity as f64;
            if post_residual < next_item_size {
                score += dead * 60.0 * (next_rel - dead).max(0.0) * 4.0;
            }
        }
    }

    // Prefer bins whose residual is below mean (tighter packing target),
    // penalize placing into unusually empty bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Discourage opening a new bin when good fits exist among open bins.
    if bin_residual == bin_capacity {
        let mut penalty = 250.0;
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            penalty -= 100.0; // opening a bin that won't chain is worse
        }
