pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to hold the next item
    // (waste) but reward residual that can exactly host the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx && post_residual > 0 {
            score += 6.0 * (1.0 - (post_residual as f64) / nx);
        } else if (post_residual as f64) >= nx {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Many open bins: prefer consolidating into existing bins (load balancing).
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap.max(1.0));
    score += 0.05 * pressure;

    // Prefer bins whose residual is far below the mean residual
    // (fill the emptier bins first keeps mean residual high & flexible).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev;

    // Dynamic time horizon: early in the stream, be conservative about
    // opening new bins; late in the stream, allow tight new-bin packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current bin fits are poor.
        let poor_fit = (post_residual as f64) / cap;
        score = cap - 8.0 * (1.0 - progress) + 20.0 * (1.0 - poor_fit);
        if next_item_size > 0 && item_size + next_item_size as u32 <= bin_capacity {
            score -= 6.0; // new bin can host a perfect pair
        }
    }

    // Slight preference for placing large items early (they are harder).
    score -= (item_size as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with non-linear (quartic-ish) shaping
    let mut score = post * (1.0 + 0.5 * post / cap) + (post / cap).powi(4) * cap;

    // Reward tight fits: small post_residual relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * (1.0 - post / cap);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: penalize leaving residual that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 8.0 * (1.0 - post / nxt.max(1.0));
        } else if post == nxt {
            score -= 15.0; // perfect lookahead fit
        }
    } else {
        // last item: strongly prefer filling a bin as much as possible
        score -= 40.0 * (1.0 - post / cap);
    }

    // Stream-progress coupling: later in stream, be greedier about filling bins
    score -= 10.0 * progress * (1.0 - post / cap);

    // Penalize when this bin's residual deviates badly from mean residual
    score += 0.15 * (post - mean_residual).abs();

    // Mild penalty for opening new bins when many bins are open and fit exists
    if bin_residual == bin_capacity {
        score += 12.0 + 6.0 * (open_bins_count as f64).sqrt();
