            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division thresholds on capacity fractions.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Class the post residual into quarters of capacity.
    let q = post_residual / (bin_capacity / 4);
    match q {
        0 => score += 60.0,        // tiny dead space -> very bad
        1 => score += 15.0,
        2 => score -= 10.0,
        3 => score -= 25.0,        // large residual -> good
        _ => score -= 35.0,
    }

    // Modulo arithmetic: penalize residuals that are "awkward" mod common item sizes.
    let awkward = |r: u32| -> f64 {
        let mut pen = 0.0;
        for m in [10u32, 20, 25, 50] {
            let d = r % m;
            if d > 0 {
                pen += (m as f64 - d as f64).min(d as f64) * 0.8;
            }
        }
        pen
    };
    score += awkward(post_residual);

    // Lookahead coupling: reward if next item exactly fits post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            // next item fits: judge resulting gap class
            let npost = post_residual - next_item_size;
            if npost <= 5 {
                score -= 30.0; // near-perfect two-step packing
            } else if npost > bin_capacity / 2 {
                score -= 10.0;
            } else {
                score += awkward(npost) * 0.5;
            }
        } else {
            score += 20.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        // base new-bin score: near mean residual, slightly above good fits
        score = cap_f * 0.5 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 25.0; // big item coming: fresh bin useful
        }
        if post_residual as f64 > 0.0 {
            // never actually chosen unless open bins score worse; keep it high-ish
            score += 10.0;
        }
    }

    // Progress pressure: late in stream, prefer tighter packing (lower post residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * 0.15 * progress;

    // Mean residual coupling: when open bins are already loose, prefer tight fits.
    score += (mean_residual - post) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits leftover, with slack shaping.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer leaving slack exactly equal to a plausible future item size.
            let slack_match = if slack as u32 == next_item_size { 120.0 } else { 0.0 };
            score -= 220.0 - slack * 0.6 + slack_match;
            if next_item_size == post_residual {
                score -= 550.0; // chained perfect fit
            }
        } else {
            // Dead-space penalty: leftover too small for the next item.
            let dead = post_residual as f64 / cap;
            let next_rel = next_item_size as f64 / cap;
            if post_residual < next_item_size {
                // Scale by fraction of stream remaining: dead space early is worse.
                let remaining = 1.0 - (step_index as f64 / total_items.max(1) as f64);
                score += dead * (next_rel - dead).max(0.0) * 260.0 * (0.4 + 0.6 * remaining);
            }
        }
    }

    // Prefer bins whose residual is below mean (tighter packing target).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Relative-fit bonus: reward placing the item as a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.8 && bin_residual != bin_capacity {
        score -= 90.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 180.0;
    }

    // New-bin candidate logic: open a new bin only when no open bin fits well
    // or when the current best open-bin residual is badly fragmented.
    if bin_residual == bin_capacity {
        let mut penalty = 260.0;
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            penalty -= 110.0; // opening a bin that won't chain is worse
        }
        if fitting_bins_count > 0 && post_residual < item_size {
            penalty += 60.0;
        }
        // If open bins are plentiful and fragmented, a fresh bin is more acceptable.
        let avg_res = mean_residual.max(0.0);
