    }

    // Mild late-stream pressure to consolidate into fewer bins.
    score -= progress * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Harmonic deviation term from parent, kept mild.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 1.0;

    score
}
